const capacite = Number(document.querySelector("#app").dataset.capacite);
function App() {
  const [lecture, setLecture] = useState(0);
  const [jardin, setJardin] = useState(0);
  const total = lecture + jardin;
  const reste = capacite - total;
  function ajouterLecture() { if (total < capacite) { setLecture(n => n + 1); } }
  function ajouterJardin() { if (total < capacite) { setJardin(n => n + 1); } }
  function repartir() { setLecture(0); setJardin(0); }
  return <main><p id="lecture-total">{lecture}</p><p id="jardin-total">{jardin}</p><p id="total">{total}</p><p id="reste">{reste}</p><button id="lecture-plus" type="button" disabled={reste === 0} onClick={ajouterLecture}>Une place Lecture</button><button id="jardin-plus" type="button" disabled={reste === 0} onClick={ajouterJardin}>Une place Jardin</button><button id="reset" type="button" onClick={repartir}>Repartir</button></main>;
}
root.render(<App />);

